const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.recipe_id) errors.push('recipe_id');
if (!body.discord_user_id) errors.push('discord_user_id');
if (!body.content) errors.push('content');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Validate content length
const content = body.content.trim();
if (content.length === 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Le commentaire ne peut pas etre vide',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

if (content.length > 500) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Le commentaire ne peut pas depasser 500 caracteres',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    recipe_id: body.recipe_id,
    discord_user_id: body.discord_user_id,
    discord_username: body.discord_username || null,
    content: content
  }
}];

const apiResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

const statusCode = apiResponse.statusCode || 200;
const body = apiResponse.body || apiResponse;

if (statusCode >= 400 || !body || body.detail) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Recette '${inputData.recipe_id}' non trouvee`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

return [{
  json: {
    found: true,
    recipe_id: body.id || inputData.recipe_id,
    recipe_title: body.title || 'Recette sans titre',
    creator_discord_user_id: body.discord_user_id,
    commenter_discord_user_id: inputData.discord_user_id,
    commenter_username: inputData.discord_username,
    content: inputData.content
  }
}];

const apiResponse = $input.first().json;
const recipeData = $('Check Recipe').first().json;

const statusCode = apiResponse.statusCode || 200;
const comment = apiResponse.body || apiResponse;

if (statusCode >= 400 || comment.detail) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode >= 400 ? statusCode : 500,
        message: comment.detail || 'Erreur lors de la creation du commentaire',
        status: 'API_ERROR'
      }
    }
  }];
}

// Build response
const response = {
  success: true,
  comment: {
    id: comment.id,
    recipe_id: comment.recipe_id || recipeData.recipe_id,
    discord_user_id: comment.discord_user_id,
    content: comment.content,
    created_at: comment.created_at
  }
};

// Add notify if creator != commenter
if (recipeData.creator_discord_user_id && 
    recipeData.creator_discord_user_id !== recipeData.commenter_discord_user_id) {
  response.notify = {
    type: 'new_comment',
    to_discord_user_id: recipeData.creator_discord_user_id,
    recipe_id: recipeData.recipe_id,
    recipe_name: recipeData.recipe_title,
    from_username: recipeData.commenter_username || recipeData.commenter_discord_user_id,
    preview: recipeData.content.substring(0, 100) + (recipeData.content.length > 100 ? '...' : '')
  };
}

return [{ json: response }];
